    // Reward tight fits (waste ratio low).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - waste_ratio);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Next-item lookahead: reward residuals that can host the next item, penalize those that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: bins far below mean residual are better targets for filling.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // Allow opening a new bin early in the stream when few bins exist.
        if open_bins_count < 2 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin is fine.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

