        // (large dead space) or when few bins can fit the item.
        let poor_fit = (post_residual as f64 / bin_capacity as f64).max(0.0);
        score = 55.0 + 40.0 * (1.0 - poor_fit);
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits: must open new bin
        }
        if fitting_bins_count == 1 {
