    score += (1.0 - t) * (pr / cap) * 15.0; // early: penalize large committed residuals less... keep flexibility by penalizing extremes

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (fill the fullest bins).
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 8.0 * (open_bins_count as f64).ln().max(1.0);
