        score += 3.0 * pr;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 3.0 * t;
    }

    // Penalize the fresh-bin candidate mildly unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        let pressure = if open_bins_count > 0 { 1.0 / open_bins_count as f64 } else { 1.0 };
        score += 5.0 - 4.0 * fragmentation * fragmentation - 2.0 * pressure * t;
    } else {
        // Slight preference for bins tighter than the mean (best-fit flavor).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 1.5 * dev;
    }

    score
}

