        1 => score -= 12.0 + (15 - post_residual) as f64 * 0.8,
        2 => score += 4.0,
        _ => score += 18.0 + (post_residual - 35) as f64 * 0.35,
    }

    // Integer-division thresholds: post_residual divisible by common item sizes
    // (harmonic divisibility) suggests a future perfect fill.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 6.0;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nxt_class = if next_item_size >= 50 { 0 } else if next_item_size >= 25 { 1 } else { 2 };
            score -= match nxt_class {
                0 => 10.0,
                1 => 6.0,
                _ => 2.0,
            };
        } else {
            // Next item cannot use this leftover: penalize large leftovers more.
            score += (post_residual.min(next_item_size.saturating_sub(1))) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave an awkward residual in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0
            - (item_size as f64 / 100.0) * 30.0
            + mean_residual * 0.25
            - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild preference for fuller bins relative to the mean residual.
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Modulo-class tiebreak on bin_residual: bins whose residual is in a
    // "harmonic" band (multiples of 25) are slightly preferred targets.
    if bin_residual % 25 == 0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals too small for the minimum item size are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard penalty for unusable slivers
    } else if post_residual < 20 {
        score += 25.0; // risky small gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else {
        // Usable residual: reward larger, more flexible leftover space mildly
        score -= 0.05 * post_residual as f64;
    }

    // Reward tight fits: small post_residual relative to item size means high utilization
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large
    if bin_residual != bin_capacity {
        score += 0.8 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Lookahead: prefer bins whose leftover can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual coupling: bins far below average residual are "loose" — slight penalty
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: keep it neutral-to-slightly-attractive only when current fits are bad
    if bin_residual == bin_capacity {
        score += 5.0; // default: prefer reusing an open bin
        // but if the best alternative would waste most of a bin, allow opening
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }
    // Next item cannot fit in the resulting residual: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward bins whose residual is tighter than the mean (good packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate mildly, unless it's early or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / 10.0).min(3.0);
        score += 20.0 + progress * 15.0 - pressure * 5.0;
        // Opening a new bin is fine if the next item is large and nothing matches well.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0;
        }
    }

    // Slight penalty for very small unusable fragments.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: small leftover slivers that nothing (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 6.0 * next_fit;
        } else {
            // Next item cannot use leftover: mild penalty proportional to mismatch.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless it avoids
    // fragmenting many existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let base_penalty = 10.0 + 6.0 * open_bins_count as f64;
        // Late in the stream, opening bins is cheaper (less future to amortize).
        let time_relief = 8.0 * progress;
        // If existing bins fit poorly (item barely fits), opening a new bin is fine.
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += base_penalty - time_relief - 10.0 * poor_fit;
        // Never open a new bin when a perfect fit exists elsewhere.
        if fill_ratio > 0.9 && bin_residual < bin_capacity {
            score += 100.0;
        }
    }

    // Global context: prefer placing into bins with residuals near the mean
    // (keeps bin residuals homogeneous, easier to combine later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with larger residual when many bins are open
    // (consolidate into emptier bins first keeps tight bins for tight items).
    score -= 0.01 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling of post residual with stream progress:
    // early in stream, mild waste penalty; late, aggressive waste penalty.
    let progress_coupling = x * x * (1.0 + 3.0 * progress) - x * progress * 0.5;
    score += 40.0 * progress_coupling;

    // Dead-space danger: residual too small to ever be useful (below min item size)
    let min_item = 1.0f64;
    let deadness = ((min_item - pr).max(0.0)) / cap;
    score += 60.0 * deadness * (1.0 + progress);

    // Lookahead synergy: reward bins whose post residual fits the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        let fit_bonus = (-fit_gap / cap).exp();
        score -= 25.0 * fit_bonus * (1.0 + progress);
        // penalize post residual that neither fits next item nor is usable
        let unusable = if pr < nx { (nx - pr) / cap } else { 0.0 };
        score += 15.0 * unusable * unusable;
    }

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Scarcity of fitting bins: smooth reward when few alternatives exist
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 10.0 * scarcity;

    // Mean residual coupling: prefer bins close to the fleet mean (balance),
    // with smooth quadratic deviation term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + progress);

    // New-bin candidate: empty bin. Penalize opening a new bin unless the item
    // is large relative to capacity or existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        let fill_pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let item_ratio = item_size as f64 / cap;
        let penalty = 45.0 * (1.0 - item_ratio) * (1.0 - fill_pressure) * (1.0 - 0.5 * progress);
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Class A: post_residual in [1..=10] -> excellent fill, strong reward.
    if post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Class B: post_residual in (10..=20] -> good.
    else if post_residual <= 20 {
        score -= 20.0 + (20 - post_residual) as f64 * 2.0;
    }
    // Class C: (20..=35] -> moderate.
    else if post_residual <= 35 {
        score -= 8.0;
    }
    // Class D: (35..=50] -> half-empty bin, mild penalty.
    else if post_residual <= 50 {
        score += 5.0;
    }
    // Class E: >50 -> large dead space, penalize proportionally.
    else {
        score += 15.0 + (frac - 0.5) * 60.0;
    }

    // Modulo arithmetic on post_residual: residues divisible by 5 or 10 are
    // more reusable by typical item sizes (multiples of 5/10 common).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        // Odd/unusual residues are harder to fill.
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect harmonic pairing with lookahead: huge reward.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward scaled by tightness of fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.4;
        } else {
            // Next item won't fit: if post residual can't hold anything
            // typical (small), residual is dead weight; penalize.
            if post_residual < 10 {
                score -= 5.0; // near-full anyway, acceptable
            } else {
                score += 6.0;
            }
        }
    } else {
        // Last item: minimize residual strictly.
        score += frac * 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are all crowded
    // (mean residual low) or many bins already struggle to fit items.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if existing bins would leave very fragmented space, allow it.
        if fitting_bins_count > 0 {
            let best_alt_post = if item_size <= bin_residual { 0 } else { 0 };
            let _ = best_alt_post;
            // If mean residual is large, open bins have room -> discourage new bin.
            score += (mean_residual / cap) * 40.0;
        }
        // Early in stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
        // Many open bins relative to progress: discourage more bins.
        if open_bins_count > 4 {
            score += (open_bins_count as f64 - 4.0) * 3.0;
        }
    }

    // Tie-break: prefer bins with residual closest to item size (tight fit)
    // via integer division ratio.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        if ratio > 0.9 {
            score -= 15.0;
        } else if ratio > 0.7 {
            score -= 7.0;
        } else if ratio < 0.3 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // future item (<= 1) are worthless; penalize small-but-nonzero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32) as f64 * 3.0;
    }

    // Reward near-perfect fills strongly (subtracted, so lower = better).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already tight relative to mean residual:
    // packing into the fullest bin is classic best-fit behavior.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): apply open-bins pressure. Opening a new
    // bin is only attractive when existing bins are already crowded or the
    // fit would leave a large dead gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = open_bins_count as f64 / 8.0;
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + crowding * 10.0 - waste * 0.3;
        // Lookahead: opening a new bin is good if next item also needs space.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins when they leave room for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // would block the next item's natural fit
        }
    }

    // Mild stream-pressure: as the stream progresses, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += is_new_bin as i32 as f64 * progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin residual after placement exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward closeness to a perfect chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack);
        } else {
            // Next item won't fit here: penalize dead space, worse when tiny.
            let dead = post_residual as f64;
            score += dead * (1.0 + 0.5 * (1.0 - dead / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly prefer using it rather than leaving it to die.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (better consolidated fill).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 50.0; // new bin less attractive if next item is big
        }
    }

    // Late in stream: consolidate harder, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving a residual that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space penalty
    }

    // Lookahead coupling: reward if next item can fit into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Bonus if next item exactly matches post-residual (perfect chaining).
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 4.0;
        }
        // Penalize if this bin is the only option and post-residual wastes the next item's fit elsewhere.
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing open bins generally.
        score += 6.0;
        // But if open bins are nearly full on average, opening fresh is fine.
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 14.0 * crowding;
        // Early in the stream, having few bins, opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is attractive.
        score -= 4.0 * (item_size as f64 / bin_capacity as f64);
        // Many open bins: discourage spreading.
        score += 0.6 * open_bins_count as f64;
    } else {
        // Favor bins whose residual is close to the item (best-fit flavor).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * gap;
        // Slight preference to consolidate into fewer bins when many are open.
        score += 0.2 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins with below-average residual (they are the "fuller" ones).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Late-stream tightening: as the stream ends, minimize wasted capacity more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.35 * progress * progress);

    // Penalize dead space more aggressively as the stream matures
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits (small post residual), smoothly scaled
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Mild penalty when bin is far from mean residual (fragmentation signal)
    score += 0.15 * ((pr - mean_residual).abs() / cap) * (1.0 + progress);

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, but dead space
    // below the minimum item size (1) is never useful, so add a harmonic
    // penalty for awkward residuals.
    let pr = post_residual;
    if pr > 0 {
        // Harmonic-class penalty: residual buckets via integer division.
        // Small residuals (< 10) are near-waste; penalize them extra.
        if pr < 10 {
            score -= 30.0; // nearly perfect fill
        } else {
            // Class the residual by decade: 10-19, 20-29, ...
            let class = pr / 10;
            // Larger classes are more reusable; discount score slightly
            score += class as f64 * 2.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // Next item fits: how much slack remains after chaining?
            let chain_slack = pr - next_item_size;
            score -= 10.0 - (chain_slack as f64) * 0.2;
        } else {
            // Next item won't fit here regardless; slight penalty for
            // leaving a residual in an awkward modulo class.
            if pr % 10 != 0 && pr >= 10 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fit would create bad dead space or when
    // many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base preference for reusing bins: empty bin gets a moderate score.
        score = 60.0;
        // If fragmentation is high (mean residual large relative to item),
        // opening a fresh bin is more attractive.
        let frag = mean_residual / cap;
        score -= frag * 25.0;
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 10.0;
        // If the item is large relative to capacity, a fresh bin is safer.
        score -= (item_size as f64 / cap) * 5.0;
        // If no open bin leaves a good residual, prefer new bin.
        if post_residual < 10 && bin_residual > item_size {
            score -= 20.0;
        }
    }

    // Mild global pressure: with many open bins, favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1) can use are
    // impossible, but tiny gaps (< 10) are nearly useless for a wide item range.
    // Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item is large or no bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() * 6.0;
        score += 30.0 + pressure;
        if item_size >= 60 {
            score -= 45.0; // large items open fresh bins cheaply
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // lookahead: next item can't use existing space anyway
        }
    }

    // Open-bin pressure: too many open bins -> favor reusing existing space.
    score += open_bins_count as f64 * 0.8;

    // Reward bins tighter than the current mean residual (good consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: avoid leaving a gap that barely misses the next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.6;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // this bin stays useful for the next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin becomes exactly the size of the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item still fits comfortably after this placement.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: next item can no longer use this bin.
    else if next_item_size > 0 && next_item_size <= post_residual + item_size.max(1) {
        // unreachable guard, kept for clarity
    }
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalize small unusable gaps more than large ones.
        let gap = post_residual as f64;
        score += 40.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with below-mean residual (consolidate waste into fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Mild preference to keep number of open bins low late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 25.0 + 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: early stream -> conservative (keep bins flexible), late -> pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward tight fits; penalize large dead space non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_residual = post_residual - next_item_size;
        if chain_residual == 0 {
            score -= 300.0;
        } else {
            score -= 40.0 - (chain_residual as f64 / bin_capacity as f64) * 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty unless post_residual is tiny anyway.
        if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, heavily favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 + 50.0 * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream when mean residual is high.
        let mut new_bin_cost = 120.0;
        // If open bins are congested (high mean residual relative to item), opening is more attractive.
        let congestion = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 1.0 };
        new_bin_cost -= (congestion - 1.0).max(0.0) * 60.0;
        // Early stream: prefer accumulating open bins slowly; late: avoid bin explosion.
        new_bin_cost += progress * 40.0 - (1.0 - progress) * 20.0;
        // Few fitting bins -> new bin is a reasonable fallback.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 30.0;
        }
        score += new_bin_cost;
    }

    // Mild penalty for using a bin whose residual is much larger than needed when many bins exist
    // (preserve large-residual bins for larger future items).
    if bin_residual > bin_capacity && false { score -= 0.0; }
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Core: post-residual with quadratic self-coupling (penalize large AND tiny leftovers)
    let mut score = pr + 40.0 * norm_pr * (1.0 - norm_pr) * cap * norm_item;

    // Smooth interaction: dead-space penalty grows with stream progress
    score += 30.0 * progress * norm_pr * norm_pr * cap;

    // Tightness reward: near-exact fits favored more as stream advances
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * tight * (0.5 + progress);

    // Lookahead coupling: smooth reward if next item likely fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_prob = (norm_pr - nx).max(0.0) * (1.0 - (norm_pr - nx).max(0.0));
        score -= 15.0 * fit_prob * (1.0 - progress);
        // penalize leaving residual just below next item size (smooth barrier)
        let gap = nx - norm_pr;
        if gap > 0.0 && gap < 0.25 {
            score += 20.0 * (0.25 - gap) * (0.25 - gap) * 16.0;
        }
    }

    // Scarcity pressure: last fitting bin gets smooth bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual deviation coupling (poly)
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: smooth penalty scaled by how many bins exist and progress
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // but allow new bin if all open bins are nearly full (smooth)
        let fullness = 1.0 - mean_residual / cap;
        score -= 30.0 * fullness * fullness * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 0.01;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    // Residuals in small classes (0..=5) are near-perfect; reward heavily.
    let pr = post_residual;
    let class = pr / 25; // 0: [0,25), 1: [25,50), 2: [50,75), 3: [75,100]
    score -= match class {
        0 => 4.0,
        1 => 1.5,
        2 => 0.5,
        _ => 0.0,
    };

    // Perfect fill bonus
    if pr == 0 {
        score -= 10.0;
    }

    // Modulo coupling: does next_item_size fit into post_residual exactly?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, stronger if it fills well.
            let nxt_post = pr - next_item_size;
            score -= 3.0 + (nxt_post as f64) * 0.02;
            // Harmonic chain: next item's own residual class
            if nxt_post / 25 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot fit here: penalize slightly, less if many bins open.
            score += 1.0 + (next_item_size as f64) * 0.01;
        }
        // Exact divisor harmony: pr % next_item_size == 0 means perfect future stacking
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 2.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But early in stream, opening bins is fine to build diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 {
            score -= 10.0;
        }
        // If next item is huge and current item small, a fresh bin is attractive.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a straggler — use it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.03;

    // Many open bins: encourage consolidation (prefer bins, not new ones).
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Refined post-residual classes with sharper low-residual rewards.
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        score -= 20.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual <= 35 {
        score -= 8.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 15.0 + (frac - 0.5) * 60.0;
    }

    // Divisible residues are more reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Lookahead: how well does next item pair with the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Extra reward when slack is tiny (tight two-item pairing).
            let tight_bonus = if slack <= 3.0 { 10.0 } else { 0.0 };
            score -= 25.0 - slack * 0.4 + tight_bonus;
        } else {
            // Next item doesn't fit here: check if residual can hold
            // small items in general; large residuals waste space.
            if post_residual < 10 {
                score -= 5.0;
            } else if post_residual < next_item_size {
                score += 6.0 + (post_residual as f64) * 0.1;
            } else {
                score += 6.0;
            }
        }
        // If next item also fits the current bin (double lookahead),
        // this bin is highly valuable: item + next item both consumable.
        if next_item_size + item_size <= bin_residual {
            score -= 18.0;
        }
    } else {
        score += frac * 10.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count > 0 {
            // Open bins have room: discourage new bin proportionally.
            score += (mean_residual / cap) * 40.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
        if open_bins_count > 4 {
            score += (open_bins_count as f64 - 4.0) * 3.0;
        }
        // If the item is large relative to capacity and no open bin fits
        // it well, opening a new bin is correct regardless of count.
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 45.0;
        }
    }

    // Tight-fit tie-break via ratio, with a hard reward for near-exact fits.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        if ratio > 0.95 {
            score -= 22.0;
        } else if ratio > 0.9 {
            score -= 15.0;
        } else if ratio > 0.7 {
            score -= 7.0;
        } else if ratio < 0.3 {
            score += 8.0;
        }
        // Exact fit bonus.
        if bin_residual == item_size {
            score -= 25.0;
        }
    }

    // Late-stream consolidation: as we approach the end, prioritize
    // minimizing residual waste even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += pr * 0.15 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: post_residual in [1..=10] -> excellent fill, strong reward.
    if post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Class B: (10..=20] -> good.
    else if post_residual <= 20 {
        score -= 20.0 + (20 - post_residual) as f64 * 2.0;
    }
    // Class C: (20..=35] -> moderate.
    else if post_residual <= 35 {
        score -= 8.0;
    }
    // Class D: (35..=50] -> half-empty bin, mild penalty.
    else if post_residual <= 50 {
        score += 5.0;
    }
    // Class E: >50 -> large dead space, penalize proportionally.
    else {
        score += 15.0 + (frac - 0.5) * 60.0;
    }

    // Modulo arithmetic on post_residual: reusable residues rewarded.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.4;
        } else {
            if post_residual < 10 {
                score -= 5.0;
            } else {
                score += 6.0;
            }
        }
    } else {
        score += frac * 10.0;
    }

    // Last-chance bin: prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // NEW MUTATION: two-step lookahead chain. If the next item fits tightly
    // AND the item after it (approximated via next_item_size class) would
    // also fit the resulting residual, add a compounding reward. This
    // rewards bins that seed a chain of tight fills.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_slack = post_residual - next_item_size;
        if second_slab_like(second_slack) {
            score -= 12.0;
        }
    }

    // NEW MUTATION: waste-aware new-bin gating. Compare the residual this
    // placement leaves (post_residual) against the mean residual of open
    // bins. If this placement produces a residual notably BELOW the mean,
    // it is compacting the fleet: extra reward. If it produces a residual
    // far above the mean, it spreads waste: penalty.
    if bin_residual != bin_capacity && post_residual > 0 {
        let delta = (post_residual as f64 - mean_residual) / cap;
        if delta < -0.02 {
            score -= (-delta) * 45.0;
        } else if delta > 0.05 {
            score += delta * 35.0;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        if fitting_bins_count > 0 {
            // If mean residual is large, open bins have room -> discourage new bin.
            score += (mean_residual / cap) * 40.0;
        }
        // NEW MUTATION: open a fresh bin early only if the current item is
        // large relative to capacity (big items seed well-structured bins);
        // otherwise force compaction into existing bins.
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 {
            score -= 18.0;
        }
        // Early in stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
        // Many open bins relative to progress: discourage more bins.
        if open_bins_count > 4 {
            score += (open_bins_count as f64 - 4.0) * 3.0;
        }
        // NEW MUTATION: if the next item is large and no open bin could hold
        // it after this placement, opening a fresh bin now preserves a
        // large contiguous space elsewhere — slight discount.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0;
        }
    }

    // Tie-break: prefer bins with residual closest to item size (tight fit).
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        if ratio > 0.9 {
            score -= 15.0;
        } else if ratio > 0.7 {
            score -= 7.0;
        } else if ratio < 0.3 {
            score += 8.0;
        }
    }

    score
}

// Helper: residual slack small enough to be considered "chain-fillable"
// by typical small items (<= 15 units of slack keeps space usable).
#[inline]
fn second_slab_like(slack: u32) -> bool {
    slack <= 15
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space avoidance: tiny gaps are nearly useless; penalize super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classing of post_residual (borrowed from best heuristic):
    if post_residual >= 10 && post_residual <= 20 {
        score -= 20.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score -= 8.0;
    } else if post_residual > 35 && post_residual <= 50 {
        score += 5.0;
    } else if post_residual > 50 {
        score += 15.0 + (pr / cap - 0.5) * 60.0;
    }

    // Reusable residues (multiples of 5/10) are more likely filled by future items.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual > 0 && post_residual % 5 == 0 {
