    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // an existing bin fits well; make new bins less attractive as
    // open_bins_count grows.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
