    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: minimize wasted space, with non-linear penalty for tiny unusable gaps
    let mut score = pr as f64;
    score += 30.0 * (1.0 - x) * (1.0 - x); // reward tight fits (small post_residual)
    score -= 20.0 * x * x;                 // reward bins that end up nearly empty-capacity used

    // Smooth coupling with stream progress: early on tolerate slack, later be strict
    let tight_bias = (0.5 - progress).tanh(); // positive early, negative late
    score += 15.0 * tight_bias * x;
    score -= 10.0 * progress * (1.0 - x) * (1.0 - x);

    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 12.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 && next_item_size <= item_size {
        // post residual too small for next item: penalize more as stream advances
        score += 8.0 * (1.0 - progress);
