    // New-bin candidate: keep it attractive early, discourage late when many bins open
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress) * (1.0 - progress);
        score += 5.0 * (open_bins_count as f64).ln() * (0.5 + progress);
    }

    score
}

