pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: waste term with non-linear penalty on small residuals
    let mut score = pr + 40.0 * (1.0 - norm_pr) * norm_pr * (1.0 - norm_pr);

    // Smooth coupling of residual with stream progress: early stream tolerates
    // slack, late stream penalizes it quadratically.
    let prog_coupling = 1.0 + 2.5 * progress * progress;
    score *= prog_coupling;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
