    // item sizes (10, 20, 25, 50) are reusable by future items.
    let reusable = |r: u32| -> f64 {
        let mut best = 0.0;
        for m in [10u32, 20, 25, 50] {
            let rem = r % m;
            let d = rem.min(m - rem) as f64;
            best = best.max((m as f64 / 10.0) * (1.0 - d / (m as f64 / 2.0)));
        }
