    } else if post_residual <= 20 {
        score -= 15.0 + (20 - post_residual) as f64 * 2.2;
    } else if post_residual <= 35 {
        score -= 4.0;
    } else if post_residual > 50 && post_residual < 100 {
        score += 6.0; // residual no typical item can cleanly fill
    }

    // Round residuals are reusable by common sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 10.0;
        } else if post_residual % 5 == 0 {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead: pair with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 65.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let mut bonus = 20.0 - slack * 0.35;
            if slack <= 5.0 {
                bonus += 9.0;
            }
            score -= bonus;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
    }

    // Last-chance bin: prefer the sole fitting open bin over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 42.0;
    }

    // Anti-fragmentation: consolidate when many bins but few fits.
    if fitting_bins_count >= 1 && bin_residual != bin_capacity {
        let pressure = open_bins_count as f64 / (fitting_bins_count as f64 + 1.0);
        score -= pressure * 2.0;
    }

    // New-bin candidate: adaptive gate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 50.0 + progress * 40.0;

        if mean_residual / cap > 0.15 {
            open_cost += 30.0;
        } else if mean_residual / cap < 0.08 {
            open_cost -= 18.0;
        }
        if open_bins_count > 4 {
            open_cost += (open_bins_count as f64 - 4.0) * 3.0;
        }
        open_cost -= (1.0 - progress) * 22.0;

        if item_size as f64 > mean_residual {
            open_cost -= 12.0;
        }
        if item_size >= 60 {
            open_cost -= 10.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            open_cost -= 6.0;
        }
        // Sole fitting bin would leave a tiny sliver: opening is better.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            open_cost -= 28.0;
        }
        score += open_cost;
    }

    // Tight-fit tie-break.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        if ratio > 0.95 {
            score -= 20.0;
        } else if ratio > 0.9 {
            score -= 12.0;
        } else if ratio > 0.7 {
            score -= 6.0;
        } else if ratio < 0.3 {
            score += 7.0;
        }
    }

    // Consolidation reward: bins tighter than mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else if bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 0.5 * item_size as f64;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.6;
        if slack == 0.0 {
            score -= 15.0;
        }
    }
    // Next item does NOT fit after this placement: penalize creating dead space,
    // unless the dead space is small (tight fit is still good).
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        if dead <= 10.0 {
            score -= 10.0; // small unusable gap, acceptable
        } else {
            score += dead * 0.15;
        }
    }

    // Tightness reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean adjustment: bins with residual below mean are more "loaded",
    // prefer packing into them to consolidate.
    if bin_residual < bin_capacity {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += diff * 12.0;
    }

    // Penalize opening a new bin when the item fits comfortably in an existing one.
    if bin_residual == bin_capacity {
        let fits_well = open_bins_count > 0 && fitting_bins_count > 0
            && (bin_residual - item_size) <= 30;
        if fits_well {
            score += 25.0;
        } else if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        } else {
            score += 5.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    score
}

