pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: exact-fill classes are gold.
    let post_class = post_residual / 10; // 0..10 classes
    match post_class {
        0 => score -= 40.0,               // perfect fit
        1 => score -= 25.0,               // near-perfect
        2 => score -= 12.0,
        3 => score -= 6.0,
        4 => score -= 2.0,
        5 => score += 2.0,                // half-full: mediocre
        6 => score += 4.0,
        7 => score += 6.0,
        8 => score += 10.0,
        _ => score += 14.0,               // large dead space
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, but only if the fit is tight
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 18.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize bins that strand capacity
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
            // harmonic penalty if post_residual falls just below a "useful" class
            if post_class >= 3 && post_class <= 6 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Scarcity pressure: few fitting bins -> prefer using existing bins.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= 3.0 * (fitting_bins_count as f64).min(6.0);
    }

    // New-bin candidate: penalize opening a bin unless existing bins are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // early stream: opening bins is cheaper; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: if this bin is much tighter than average, prefer it.
    score -= (mean_residual - post).clamp(-30.0, 30.0) * 0.4;

    // Prefer filling bins that are already mostly used.
    score -= (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    let mut score = post_residual as f64;

    // Graded compaction classes with dead-space penalties.
    if post_residual == 0 {
        score -= 90.0; // perfect fill is gold
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual <= 20 {
        score -= 20.0 + (20 - post_residual) as f64 * 2.4;
    } else if post_residual <= 35 {
        score -= 5.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 13.0 + (frac - 0.5) * 60.0;
    }

    // Divisibility: round residuals are reusable by common sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 11.0;
        } else if post_residual % 5 == 0 {
            score -= 5.5;
        } else {
            score += 3.5;
        }
    }

    // Tightness reward.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;
    if bin_residual > 0 {
        let ratio = tightness;
        if ratio > 0.95 {
            score -= 20.0;
        } else if ratio > 0.9 {
            score -= 12.0;
        } else if ratio > 0.7 {
            score -= 6.0;
        } else if ratio < 0.3 {
            score += 8.0;
        }
    }

    // Two-step lookahead: pair with next item, judge leftover slack.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let mut bonus = 23.0 - slack * 0.38;
            if slack <= 5.0 {
                bonus += 10.0;
            }
            if slack > 0.0 && (slack as u32) % 5 == 0 {
                bonus += 5.0;
            }
            score -= bonus;
        } else if post_residual < 10 {
            score -= 5.0;
        } else {
            score += 6.0 + frac * 12.0;
        }
    }

    // Last-chance bin: strongly favor the sole fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 42.0;
    }

    // Anti-fragmentation pressure.
    if fitting_bins_count >= 1 && bin_residual != bin_capacity {
        let pressure = open_bins_count as f64 / (fitting_bins_count as f64 + 1.0);
        score -= pressure * 2.2;
    }

    // Mean residual coupling.
    score += 0.15 * (mean_residual - pr).max(0.0);
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else if bin_residual != bin_capacity {
        score += 3.0;
    }

    // New-bin candidate: adaptive gate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 52.0 + progress * 42.0;
        if mean_residual / cap > 0.15 {
            open_cost += 32.0;
        }
        if mean_residual / cap < 0.08 {
            open_cost -= 20.0;
        }
        if open_bins_count > 4 {
            open_cost += (open_bins_count as f64 - 4.0) * 3.2;
        }
        open_cost -= (1.0 - progress) * 24.0;
        if item_size as f64 > mean_residual {
            open_cost -= 12.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            open_cost -= 7.0;
        }
        if item_size >= 60 {
            open_cost -= 8.0;
        }
        // Prefer opening a new bin rather than leaving a tiny sliver in the sole fitting bin.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            open_cost -= 30.0;
        }
        score += open_cost;
    }

    // Waste-forecast: residuals no typical item can fill.
    if post_residual > 50 && post_residual < 100 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (post_residual 1..=9) are worthless: heavy penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Medium gaps (10..=20) are semi-usable: mild penalty scaled by waste ratio.
    if post_residual > 9 && post_residual <= 20 {
        score += 0.35 * (post_residual as f64 - 9.0);
    }

    // Reward tight fits (item fills most of the bin).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // --- Lookahead: if next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual - next_item_size <= 9 {
            score -= 20.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // --- Open-bin pressure: discourage spreading across many bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // --- Last-chance bonus: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins fit poorly
        // (large dead space) or when few bins can fit the item.
        let poor_fit = (post_residual as f64 / bin_capacity as f64).max(0.0);
        score = 55.0 + 40.0 * (1.0 - poor_fit);
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits: must open new bin
        }
        if fitting_bins_count == 1 {
            score += 10.0; // an open bin is a last chance: keep using it
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees fit for next item too
        }
    } else {
        // Favor bins with residuals close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.10 * dev;
    }

    score
}

