        let dead = (post_residual as f64 - 50.0) / 50.0;
        let mut penalty = dead * (30.0 + 50.0 * progress);
        if next_item_size > 0 && next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover > 0 && leftover < 50 {
                penalty += leftover as f64 * 0.8;
            }
        }
        score += penalty;
    }

    // Mild preference for tighter bins generally
    score -= (bin_capacity - bin_residual) as f64 * 0.22;

    // Discourage leaving residuals that no plausible item can fill
    if post_residual > 0 && post_residual < 30 {
        score -= (30 - post_residual) as f64 * 4.5;
    }

    // Avoid stranding mid-size residuals when next item is large
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && post_residual < 40 && next_item_size > 40 {
        score += (40 - post_residual) as f64 * 1.5;
    }

    // Prefer bins whose post_residual matches the next item's size class
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
    }

    // Two-item chain lookahead
    if next_item_size > 0 && next_item_size == post_residual && next_item_size > bin_capacity / 3 {
        score -= 40.0 * (1.0 - progress);
    }

    // Residual divisibility bonus
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 25 == 0 {
            score -= 18.0;
        } else if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Penalize very low utilization bins being chosen when alternatives exist
    let used = (bin_capacity - bin_residual) as f64;
    let util = used / cap;
    if util < 0.35 && open_bins_count > 2 && !is_new_bin {
        score += 25.0 * (0.35 - util) * (1.0 + progress);
    }

    // NEW: mid-range residual trap — residuals just above a plausible item size
    // (within 1..6) are the worst dead space; penalize proportionally to how
    // close the next item is to the residual, since it will strand the remainder
    if post_residual > 20 && post_residual < 60 {
        if next_item_size > 0 && next_item_size < post_residual {
            let remainder = post_residual - next_item_size;
            if remainder <= 6 {
                score += (7 - remainder) as f64 * 12.0;
            }
        }
    }

    // NEW: consolidation pressure — when many bins are open and residuals are
    // small, prefer bins that leave post_residual matching common item sizes
    // (multiples of 10 in mid-range), to enable future exact fills
    if post_residual >= 30 && post_residual <= 70 && post_residual % 10 == 0 {
        score -= 10.0 * (1.0 - progress);
    }

    // NEW: late-stream exactness — as the stream ends, only exact or near-exact
    // fills matter; sharpen the reward gradient on small post_residuals
    if progress > 0.7 && post_residual > 0 {
        score += post_residual as f64 * 0.35 * (progress - 0.7) / 0.3;
    }

    score
}

