pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Tiered dead-space avoidance (sharpened tiers) ---
    if post_residual == 0 {
        score -= 900.0; // perfect fit: dominant reward
    } else if post_residual <= 4 {
        score -= 220.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 18 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score += 0.35 * (post_residual as f64 - 18.0);
    }

    // Small unusable gaps are worthless
    if post_residual > 0 && post_residual <= 9 {
        score += 45.0;
    }

    // Reward tight fills
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // --- Lookahead: next item consumes post_residual ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 550.0;
            if next_item_size > bin_capacity / 3 {
                score -= 35.0 * (1.0 - progress);
            }
        } else if next_item_size < post_residual {
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 0.9;
            if two_step_waste <= 8 {
                score -= 70.0;
            }
        } else {
            // next item won't fit here
            let gap = (next_item_size - post_residual) as f64;
            score += 18.0 + gap * 0.5 - 40.0 * fill;
            if post_residual < 40 && next_item_size > 40 {
                score += (40 - post_residual) as f64 * 1.5;
            }
        }
    }

    // --- Mean-residual pull, stronger late stream ---
    let mean_dev = post_residual as f64 - mean_residual;
    score += mean_dev * (0.25 + 0.5 * progress);

    // --- Open-bin pressure ---
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 320.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        score += 130.0 + 150.0 * progress;
        if fitting_bins_count == 0 {
            score -= 260.0; // nothing fits: must open new bin
        }
        if fitting_bins_count == 1 {
            score += 10.0;
        }
        // Fresh bin attractive when existing fits waste space for next item
        if next_item_size > 0 && next_item_size > post_residual && !post_residual == false {
            let wasted_for_next = (next_item_size - post_residual) as f64;
            score -= wasted_for_next * 0.85;
        }
        // Cheap when many bins already open
        score -= (open_bins_count as f64).ln().max(0.0) * 10.0;
        // Late stream: resist opening fresh bins
        if progress > 0.8 {
            score += 60.0 * (progress - 0.8) * 5.0;
        }
        // Pair current item with next large item in fresh bin
        if next_item_size > bin_capacity / 2 {
            score -= 85.0;
        }
        if progress < 0.3 {
            score -= 40.0 * (0.3 - progress);
        }
    } else {
        // Low-utilization bins chosen when alternatives exist
        let used = (bin_capacity - bin_residual) as f64;
        let util = used / bin_capacity as f64;
        if util < 0.35 && open_bins_count > 2 {
            score += 25.0 * (0.35 - util) * (1.0 + progress);
        }
    }

    // --- Dead-space guard for mid residuals ---
    if post_residual > 50 && post_residual < 100 {
        let dead = (post_residual as f64 - 50.0) / 50.0;
        score += dead * (30.0 + 50.0 * progress);
    }

    // --- Divisibility bonus: fillable residuals ---
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 25 == 0 {
            score -= 18.0;
        } else if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    score
}

