    if !is_new_bin && item_size as f64 > cap * 0.7 {
        score -= (bin_residual - item_size) as f64 * 0.45;
    }

    // --- NEW: mid-range residual trap detection ---
    // Residuals in the 31..=45 window are the classic dead zone: too big for
