        0 => score -= 25.0,                 // residual < 10: nearly dead, but tiny waste
        1 => score -= 8.0,                  // 10..19: can fit smallest class
        2 => score -= 4.0,                  // 20..29
        3 => score -= 2.0,                  // 30..39
        4 | 5 => score += 3.0,              // 40..59: mediocre leftover
        6 | 7 => score += 6.0,              // 60..79: poor
        _ => score += 10.0,                 // 80+: very poor use of bin
    }

    // Modulo coupling: residual divisible by common sizes is reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here regardless; mild penalty scaled by overshoot
            let over = (next_item_size - pr) as f64;
            score += 2.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer reusing open bins early; allow new bins
    // when existing residuals are large/wasteful (mean_residual high)
    if bin_residual == bin_capacity {
