    }

    // --- Dead-space ratio penalty scaled by remaining stream and alternatives ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            let alt_factor = if fitting_bins_count > 1 { 1.15 } else { 0.85 };
            score += dead_ratio * 60.0 * (0.5 + 0.5 * progress) * alt_factor;
