    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- NEW: sweep leftover residuals against mean to break ties toward consolidation ---
    if !is_new_bin && post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev < 6.0 {
            score -= 5.0;
        }
    }

    // --- Tightness reward (from best) ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 21.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable dead space (< 10 or smaller than next item).
    let dead_limit = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < dead_limit {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (waste ratio low).
    let fit = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit * fit;

    // If this bin is the only one that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // But a new bin is fine if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (compact bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: leaving exactly next_item_size is perfect.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
