            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- Mid-range residual sink ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction — squeeze harder as stream ends ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // --- NEW: dead-space coupling with mean residual — bins whose post-residual
    // exceeds the fleet mean by a lot are poor sinks for medium items; steer
    // the item toward tighter bins so residual variance shrinks.
    if !is_new_bin && post_residual > 25 {
        let excess = post_residual as f64 - mean_residual;
        if excess > 0.0 && next_item_size as f64 > post_residual as f64 {
            score += excess * 0.35 * (0.4 + 0.6 * progress);
        } else if excess < -15.0 {
            // unusually tight bin: slight extra reward to consume it while small items remain
            score -= (-excess).min(40.0) * 0.18;
        }
    }

    // --- NEW: two-step exactness probe — if item leaves a residual that itself
    // equals next_item_size, or matches a half/quarter of capacity, reward heavily.
    if !is_new_bin && post_residual > 0 {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
        if post_residual * 2 == bin_capacity || post_residual * 4 == bin_capacity {
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
