pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual). Late: tolerate larger residuals
    // to avoid opening bins for near-perfect fits that waste the new-bin option.
    let t = progress;
    let poly = pr
        - 0.9 * t * (pr * pr) / cap
        + 0.5 * t * t * (pr * pr * pr) / (cap * cap);

    let mut score = poly;

    // Dead-space penalty: residual too small for the smallest plausible next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = (nxt - pr).max(0.0) / cap;
        score += 2.5 * waste * waste * cap;
        // Reward leaving room exactly for the lookahead item.
        if pr >= nxt && pr - nxt <= 5.0 {
            score -= 6.0 * (1.0 - t);
        }
    } else {
        // Last item: any residual is pure waste; strongly favor tightest fit.
        score += 3.0 * pr;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 3.0 * t;
    }

    // Penalize the fresh-bin candidate mildly unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        let pressure = if open_bins_count > 0 { 1.0 / open_bins_count as f64 } else { 1.0 };
        score += 5.0 - 4.0 * fragmentation * fragmentation - 2.0 * pressure * t;
    } else {
        // Slight preference for bins tighter than the mean (best-fit flavor).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 1.5 * dev;
    }

    score
}

