        if open_bins_count > 4 && mean_residual > cap * 0.45 {
            score -= 15.0;
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
        if usable_ratio < 0.1 {
            score -= 12.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 14.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 5.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.55;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 56.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.05 * (0.5 + 0.5 * progress);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 11.0 * (1.0 - progress);
    }

    // --- Mid-range residual sink: prefer bins whose post-residual matches
    // common small item sizes (5..=15) to enable future exact fills
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction — squeeze harder as stream ends
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity fractions. Residuals in (0, 10] are almost unusable dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual > 0 {
        // Fraction of capacity remaining after placement
        let frac = pr / cap;
        // Harmonic bucket: 0..5 -> dead, 6..15 -> poor, 16..30 -> fair, >30 -> good
        let bucket = if post_residual <= 10 { 0.0 }
            else if post_residual <= 15 { 1.0 }
            else if post_residual <= 30 { 2.0 }
            else { 3.0 };

        match bucket as u32 {
            0 => score += 120.0,                    // dead space penalty
            1 => score += 45.0,                     // poor fit penalty
            2 => score -= 10.0,                     // fair fit reward
            _ => score -= 25.0,                     // good residual reward
        }

        // Modulo harmonic classes on post_residual: values divisible by
        // common item granularities are more reusable.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        } else {
            score += 4.0;
        }

        // Integer-division threshold: post_residual / next_item_size.
        // If the next item can exactly fill the residual, strongly reward.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                let slack = post_residual - next_item_size;
                if slack == 0 {
                    score -= 80.0; // perfect follow-up fit
                } else if slack <= 10 {
                    score += 20.0; // leaves near-dead space
                } else {
                    score -= 8.0;
                }
            } else {
                // next item won't fit here; residual is a waiting buffer
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    } else {
        // Exact fill: perfect closure
        score -= 150.0;
    }

    // Tightness reward: item fills most of the bin
    let fill = item_size as f64 / cap;
    score -= fill * 30.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it unattractive unless nothing else is decent.
    if bin_residual == bin_capacity {
        score = 250.0 + pr - (1.0 - step_index as f64 / total_items.max(1) as f64) * 20.0;
        // allow new bin early if open bins are all nearly full (mean residual low)
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins when many bins are open
    score += (open_bins_count as f64) * (mean_residual - pr) * 0.05;

    score
}

