            score += two_step_waste as f64 * 0.9;
            if two_step_waste <= 8 {
                score -= 85.0;
            }
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 52.0 * (1.0 - progress);
            } else if after_next <= 12 {
                score -= 17.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let fill_ratio = (cap - post_residual as f64) / cap;
            score += 20.0 + gap * 0.55 - 48.0 * fill_ratio;
            if post_residual < 40 && next_item_size > 40 {
                score += (40 - post_residual) as f64 * 1.6;
            }
            score += gap * 0.35 * (1.0 - progress);
        }
    }

    // --- Mean-residual pull, stronger late ---
    let mean_dev = post_residual as f64 - mean_residual;
    score += mean_dev * (0.22 + 0.55 * progress);

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && !is_new_bin && bin_residual >= item_size {
        score -= 360.0;
    }

    // --- General tightness ---
    score -= (bin_capacity - bin_residual) as f64 * 0.25;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 21.0 * tightness;

    // --- Divisibility bonus ---
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 25 == 0 {
            score -= 20.0;
        } else if post_residual % 10 == 0 {
            score -= 9.0;
        }
    }

    // --- Low-utilization bins discouraged when alternatives exist ---
    let used = (bin_capacity - bin_residual) as f64;
    let util = used / cap;
    if util < 0.35 && open_bins_count > 2 && !is_new_bin {
        score += 26.0 * (0.35 - util) * (1.0 + progress);
    }

    // --- Open-bin pressure ---
    if !is_new_bin {
        score += 0.64 * open_bins_count as f64 * (1.0 - (post_residual as f64 / cap));
    }

    // --- Large items consume bins with least remaining space ---
    if !is_new_bin && item_size as f64 > cap * 0.7 {
        score -= (bin_residual - item_size) as f64 * 0.47;
    }

    // --- Near-exact fill refinement ---
    if !is_new_bin && post_residual > 0 {
        if post_residual <= 8 {
            score -= 11.0 + (8 - post_residual) as f64 * 2.5;
        } else if post_residual <= 14 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        score += 140.0 + 160.0 * progress;
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        if fitting_bins_count == 1 {
            score += 12.0;
        }
        if next_item_size > post_residual {
            score -= (next_item_size - post_residual) as f64;
        }
        score -= (open_bins_count as f64).ln().max(0.0) * 10.0;
        if progress > 0.8 {
            score += 60.0 * (progress - 0.8) * 5.0;
        }
        if next_item_size > bin_capacity / 2 {
            score -= 95.0;
        }
        if progress < 0.3 {
            score -= 42.0 * (0.3 - progress);
        }
        if next_item_size > 0 && next_item_size <= bin_residual.saturating_sub(item_size) {
            let fresh_left = bin_residual - item_size;
            if fresh_left == next_item_size {
                score -= 210.0;
            } else if next_item_size as f64 > fresh_left as f64 {
                score += (next_item_size - fresh_left) as f64 * 0.65;
            }
        }
        if open_bins_count > 4 && mean_residual > cap * 0.45 {
            score -= 16.0;
        }
        if fitting_bins_count > 0 {
            if post_residual as f64 <= cap * 0.15 {
                score += 55.0;
            }
            if post_residual <= 6 {
                score += 78.0;
            } else if post_residual <= 12 {
                score += 30.0;
            }
        }
        let item_ratio = item_size as f64 / cap;
        if fitting_bins_count > 0 && item_ratio > 0.6 {
            score -= 25.0 * (item_ratio - 0.6) * 10.0;
        }
        if open_bins_count > 3 {
            let roomy = (mean_residual / cap).min(1.0);
            score += 22.0 * roomy * (0.6 + 0.4 * progress);
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 30.0;
        }
        // penalize fresh bin when an open bin would end nearly empty anyway
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 34.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bin late in the stream when any open bin fits —
        // consolidation matters more than fit quality near the end
        if fitting_bins_count > 0 && progress > 0.7 {
            score += 90.0 * (progress - 0.7) * 8.0;
        }
        // NEW: refuse fresh bin when the best open fit leaves a small residual
        // that could still host a small future item
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 20 {
            score += (20 - post_residual) as f64 * 4.5;
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
        if usable_ratio < 0.1 {
            score -= 13.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 15.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 6.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.6;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 58.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.1 * (0.5 + 0.5 * progress);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- mid-range residual sink — prefer bins whose post-residual matches
    // common small item sizes (5..=15) to enable future exact fills
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- late-stream compaction — squeeze harder as stream ends
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // --- NEW: dead-space gradient — prefer bins whose post-residual is closest
    // to the next item's size among all fitting bins (relative scarcity signal)
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= slack.min(25) as f64 * 0.8 * scarcity;
    }

    // --- NEW: avoid stranding mid-size residuals (25..=45) when the next item
    // cannot use them — these are prime fragmentation sources
    if !is_new_bin && post_residual >= 25 && post_residual <= 45
        && next_item_size > post_residual {
        score += (post_residual - 25) as f64 * 0.9 * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band does it live in?
    let item_class = (item_size * 4) / bin_capacity; // 0..3 (tiny, small, medium, large)
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward placements that land post_residual into a "usable" harmonic class
    // (post_residual divisible-ish into future items): post residuals that are
    // multiples of common item sizes are valuable.
    let usable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50, 80] {
            if m <= r && r % m == 0 {
                bonus += 6.0;
            }
        }
        bonus
    };
    score -= usable(post_residual);
    score += usable(bin_residual - post_residual) * 0.5; // penalize wasted chunk slightly less if it was "clean"

    // Dead-space penalty: post_residual in the lowest band (1..25) is nearly unusable
    if post_class == 0 && post_residual > 0 {
        score += 18.0;
    } else if post_class == 1 {
        score -= 2.0;
    } else if post_class == 2 {
        score -= 4.0;
    } else {
        // post_class == 3: nearly full bin, excellent
        score -= 8.0;
    }

    // Integer-division threshold on next item: if the next item fits the post
    // residual exactly or nearly, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= bin_capacity / 10 {
                score -= 12.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; if this bin becomes dead, penalize
            if post_class == 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (creates tiny dead space).
    if fitting_bins_count == 1 {
        if post_class == 0 && post_residual > 0 {
            score += 8.0; // still prefer new bin over creating garbage
        } else {
            score -= 15.0;
        }
    }

    // New-bin candidate: empty bin. Prefer it only when all fits would create
    // dead space, or when open bins are already crowded on average.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        if crowd < 0.35 {
            score -= 10.0; // open bins are roomy; don't open another
        } else {
            score += 5.0; // bins are tight; a fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress coupling: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (post_residual as f64 / bin_capacity as f64) * progress * 10.0;
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

