pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small post-residuals (< 10, min item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Fit ratio: reward placing into bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open bins pressure: discourage spreading across too many bins.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far above mean, penalize slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // stranded gap next item cannot use
        }
    }

    // New-bin candidate: only attractive when it offers more usable room than any
    // open bin would leave, i.e. when open bins are fragmented / nearly full.
    if bin_residual == bin_capacity {
        let stream_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer keeping item in an open bin when a decent fit exists; opening new bin
        // is favored when mean residual is small (bins nearly exhausted).
        score += 35.0 - 60.0 * fragmentation - 10.0 * stream_frac;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

