    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement is excellent (chain fill).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 50.0 * (post_residual as f64 / next_item_size as f64).ln();
        } else {
            // Next item won't fit: penalize dead space proportional to gap.
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score -= 300.0;
    }

    // Compare residual against mean residual across open bins:
    // favor bins whose post_residual ends up below average (tighter packing).
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.3 * mean_diff;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
        // But if next item could instead use this residual better, soften.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 80.0;
        }
    }

    // New-bin candidate (empty bin): penalize mildly so we only open a new bin
    // when no open bin offers a decent fit; scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 40.0 * progress;
