        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Slight preference for using bins with fewer alternatives when many bins fit.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

