            score += 60.0 * (progress - 0.8) * 5.0;
        }
        if next_item_size > bin_capacity / 2 {
            score -= 95.0;
        }
        if progress < 0.3 {
            score -= 42.0 * (0.3 - progress);
        }
        if next_item_size > 0 && next_item_size <= bin_residual.saturating_sub(item_size) {
            let fresh_left = bin_residual - item_size;
            if fresh_left == next_item_size {
                score -= 210.0;
            } else if next_item_size as f64 > fresh_left as f64 {
                score += (next_item_size - fresh_left) as f64 * 0.65;
            }
        }
        if open_bins_count > 4 && mean_residual > cap * 0.45 {
            score -= 16.0;
        }
        if fitting_bins_count > 0 {
            if post_residual as f64 <= cap * 0.15 {
                score += 55.0;
            }
            if post_residual <= 6 {
                score += 78.0;
            } else if post_residual <= 12 {
                score += 30.0;
            }
        }
        let item_ratio = item_size as f64 / cap;
        if fitting_bins_count > 0 && item_ratio > 0.6 {
            score -= 25.0 * (item_ratio - 0.6) * 10.0;
        }
        if open_bins_count > 3 {
            let roomy = (mean_residual / cap).min(1.0);
            score += 22.0 * roomy * (0.6 + 0.4 * progress);
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 30.0;
        }
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 34.0 * (1.0 - progress);
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
        if usable_ratio < 0.1 {
            score -= 13.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 15.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 6.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.6;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 58.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.1 * (0.5 + 0.5 * progress);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- Mid-range residual sink: prefer bins whose post-residual matches
    // common small item sizes (5..=15) to enable future exact fills ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction — squeeze harder as stream ends ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // --- NEW: variance-aware dead-space refinement. When the current bin's
    // post-residual deviates sharply from the fleet mean, it is either an
    // outlier fragment (penalize) or a near-closed bin (reward closing it). ---
    if !is_new_bin && post_residual > 0 {
        let spread = (post_residual as f64 - mean_residual).abs() / cap;
        if spread > 0.25 {
            if post_residual as f64 > mean_residual {
                // outlier large residual: dead-space risk grows with stream left
                score += spread * 26.0 * (1.0 - progress);
            } else {
                // outlier small residual: closing this bin is valuable
                score -= spread * 34.0;
            }
        }
    }

    // --- NEW: two-item lookahead pairing — if the next item leaves a residual
    // that exactly matches a plausible follow-up size band, deepen the reward ---
    if !is_new_bin && next_item_size > 0 && next_item_size < post_residual {
        let after = post_residual - next_item_size;
        if after >= 3 && after <= 18 && (after % 5 == 0 || after % 10 == 0) {
            score -= 14.0;
        }
    }

    // --- NEW: residual-vs-next gap gradient — smoother preference for bins
    // whose residual is just barely above the next item (best packing pairs) ---
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 25 {
            score -= (25 - slack) as f64 * 0.55 * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving small unusable gaps (dead space) unless item fills bin.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to preserve flexibility (best-fit tiebreak).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / (post_residual as f64).max(1.0));
        } else {
            // Penalize placements that strand a large residual the next item can't use.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low (phase of consolidation).
    if bin_residual != bin_capacity {
        let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if (bin_residual as f64) < mr {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be more willing to open fresh bins; late, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - t) * (open_bins_count as f64).ln().max(0.0) + 20.0 * t;
    }

    // Congestion: many open bins -> discourage spreading, favor existing bins.
    if bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

