pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, non-linearly coupled with stream progress
    let mut score = pr;

    // Smooth polynomial interaction: residual worth less/more depending on progress
    let coupling = 1.0 + 0.8 * progress - 0.6 * progress * progress;
    score *= coupling;

    // Penalize large dead space non-linearly (quartic-ish smooth term)
    score += 12.0 * x * x * (1.0 - x) * cap * progress;

    // Tight fits (small post_residual) get a smooth quadratic reward
    let tight = (1.0 - x).max(0.0);
    score -= 6.0 * tight * tight * item_size as f64;

    // Lookahead: reward bins whose post residual accommodates next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap * cap * 0.1;
        }
    }

    // Last-chance bonus: smooth decay with fitting bins count
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Slight preference to fill bins with low mean residual (consolidation)
    score += 0.05 * (mean_residual - pr).abs() + 0.02 * open_bins_count as f64;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
