pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quartiles
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;
    let harmonic = match post_residual / q {
        0 => 0.0,           // tiny leftover: nearly perfect fit
        1 => 8.0,           // awkward small dead space
        2 => 3.0,           // medium residual still usable
        _ => 1.5,           // large residual, fine
    };
    score += harmonic;

    // Reward exact / near-exact fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if class == 0 {
        score -= 15.0; // residual on a harmonic boundary (25/50/75)
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 12.0; // creates dead space for the next item
        }
        // Harmonic match between leftover class and next item size
        if next_item_size % q == class && class > 0 {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest packing
        score -= 20.0;
    }

    // Integer-division threshold on item size: big items prefer roomy bins
    if item_size / q >= 2 {
        score += 6.0; // penalize cramming big items into nearly-full bins
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but keep it attractive late in the stream or when mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 - 15.0 * progress - 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a bin
        }
    }

    // Prefer filling bins below mean residual (balancing bin fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Slight preference to reuse existing bins over opening new ones
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

