pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimal dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) == next {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - next;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to waste.
            score += 10.0 + (next - post_residual as f64) * 0.3;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    if mean_residual > 0.0 {
        score -= (post_residual as f64 - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize opening a new bin when good open bins exist, unless stream is early
    // and open bins are already crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 0.6;
        if fitting_bins_count > 0 {
            score += 55.0 - 20.0 * progress * (crowded as i32 as f64);
        }
    }

    // Mild tie-break: prefer bins with larger residual used up (denser bins first).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

