        if open_bins_count > 3 {
            let roomy = (mean_residual / cap).min(1.0);
            score += 22.0 * roomy * (0.6 + 0.4 * progress);
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 30.0;
        }
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 34.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bin when an open bin would leave a residual that
        // the next item can exactly consume (perfect two-step chain exists)
        if fitting_bins_count > 0 && next_item_size > 0 {
            let open_left_exact = open_bins_count > 0
                && (bin_residual.wrapping_sub(item_size)) == next_item_size;
