    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- Mid-range residual sink ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // --- NEW: two-step chain projection — estimate residual after placing
    // both the current and next item; reward exact closure, penalize
    // stranded mid-range leftovers that no typical item can absorb.
    if !is_new_bin && next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if after > 0 && after < 25 {
            // small leftover is likely reusable by common small items
            score -= (25 - after) as f64 * 0.8 * (1.0 - progress);
        } else if after >= 25 && after <= 45 {
            // stranded mid-range dead space is the main waste source
            score += (after - 25) as f64 * 1.3;
        }
    }

    // --- NEW: residual-vs-mean alignment — prefer bins whose post-residual
    // lands near the fleet mean so future items remain placeable.
    if !is_new_bin && post_residual > 0 {
        let dev = ((post_residual as f64 - mean_residual) / cap).abs();
        if dev < 0.05 {
            score -= 8.0 * (0.05 - dev) * 100.0 * (0.4 + 0.6 * progress);
        }
    }

    // --- NEW: item/residual complementarity — when item size leaves a
    // residual close to half capacity, keep it attractive for mid items.
    if !is_new_bin && post_residual >= 40 && post_residual <= 60 {
        let half_dev = (post_residual as f64 - cap * 0.5).abs();
        if half_dev < 8.0 {
            score -= (8.0 - half_dev) * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits strongly (non-linear)
    score -= 40.0 * (1.0 - residual_ratio).powi(6) * fit_ratio;

    // Penalize small dead space that likely becomes waste
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - t);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: leftover becomes dead unless small
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: only exact fill matters
        if post_residual == 0 { score -= 100.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * t;
    }

    // Penalize scattering across many open bins when residuals are plentiful
    if open_bins_count > 3 {
        let avg = mean_residual.max(1.0);
        let rel = post_residual as f64 / avg;
        if rel > 1.5 { score += 8.0 * (rel - 1.5); }
        else if rel < 0.5 { score -= 5.0; }
    }

    // New-bin candidate: attractive early, or when item is huge and no tight fit exists
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (bin_residual - item_size) > 0;
        let pressure = mean_residual / bin_capacity as f64;
        if !tight_exists || item_size >= 80 || post_residual == 0 {
