        } else if pressure < 0.15 {
            score -= 5.0 * (1.0 - t);
        } else {
            score += 15.0 * pressure + 10.0 * t;
        }
    }

    // Mild global bonus for consolidating into low-residual bins
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

