    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 4.0 * progress;

    // Mean-residual coupling: prefer bins close to mean residual (smoothness term).
    let diff = pr - mean_residual;
    score += 0.05 * diff * diff / (cap * 0.01 + 1.0);

    // Lookahead: reward leaving space for the next item, smoothly.
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 3.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (-gap / cap) * (gap / cap) * 10.0;
