        // especially if no plausible future item can fill them (items >= 10).
        let class = pr / 10; // 1..=9 harmonic bucket
        score += (class as f64) * (class as f64) * 1.5;
        // If next item cannot fit into the post-residual, this space is dead
        // until an even smaller item arrives -> penalize.
        if next_item_size > 0 && pr < next_item_size {
            score += 12.0 + (next_item_size - pr) as f64 * 0.4;
        } else if next_item_size > 0 {
            // reward leaving room for the lookahead item exactly
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (-slack * 0.15).exp();
        }
    }

    // Capacity fraction coupling: bins whose fill ratio is already high are
    // preferable targets (best-fit bias reinforcement).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual space
    // of this bin. Penalize proportionally to remaining residual, but allow
    // it when this bin's residual is tiny anyway (nothing lost).
    if bin_residual == bin_capacity {
        // Brand-new empty bin: neutral baseline slightly above good fits.
        score += 30.0;
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If no open bin fits well (item large relative to mean residual), a
