        if item_size as f64 > mean_residual + 5.0 {
            score -= 15.0;
        }
    } else {
        // Placing into an open bin: reward keeping bin count low.
        score -= 5.0;
        // When many bins are open, consolidate rather than spread.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Modulo harmonic: residuals that are multiples of 5 tend to match more
    // item sizes drawn from typical integer distributions.
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    score
}

