    if !is_new_bin && next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 20 {
            score -= (20 - after) as f64 * 1.2 * (0.6 + 0.4 * progress);
        }
        // chain exactness: residual after next item divisible by common sizes
        if after > 0 && (after % 10 == 0 || after % 25 == 0) {
            score -= 9.0;
        }
    }

    // --- NEW: scarcity-aware exactness — when few bins fit, exact fills matter more
    if !is_new_bin && post_residual == 0 && fitting_bins_count <= 2 {
        score -= 60.0 * (1.0 - progress);
