        let harm = (post_residual as f64 - mean_residual).abs();
        if harm < 8.0 {
            score -= (8.0 - harm) * 1.5;
        }
    }

    // --- NEW: penalize leaving residuals just below common item sizes (dead zones)
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
        let overshoot = next_item_size - post_residual;
        if overshoot <= 6 {
            score += (7 - overshoot) as f64 * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize superlinearly as the gap shrinks.
    if post_residual > 0 {
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0; // unusable sliver: heavy penalty
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.5; // risky gap: moderate penalty
        } else {
            // Usable residual: mild reward for larger leftover space
            score -= (post_residual as f64 - 25.0) * 0.05;
        }
    } else {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Dead-space term coupled with lookahead: leftover space that exactly fits
    // (or nearly fits) the next item is valuable, not dead.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (next_item_size as f64) * 0.6 - (slack as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: it is likely dead space
        score += (post_residual.min(next_item_size)) as f64 * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + (item_size as f64) * 0.1;
    }

    // Open-bin pressure: with many bins open, consolidate into existing bins
    // to avoid carrying excess residuals forward.
    score += (open_bins_count as f64) * 1.2;

    // Prefer bins already tighter than the fleet average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate (pristine bin): only attractive when the item leaves
    // a large, usable residual or the stream is early with few bins open.
    if bin_residual == bin_capacity {
        if post_residual >= 40 {
            score -= 8.0;
        } else {
            score += 12.0; // discourage wasting a fresh bin on a poor split
        }
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 && open_bins_count < 3 {
            score -= 5.0;
        }
    }

    // Exact-fit reward for the current item.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
