    // --- NEW: dead-space vs. scarcity coupling — when few bins can fit the item,
    // tolerate larger residuals rather than fragmenting the last usable bins
    if !is_new_bin && post_residual > 25 && fitting_bins_count <= 2 {
        let relief = (post_residual as f64 - 25.0) / cap;
        score -= relief * 30.0 * (1.0 - progress);
    }

    // --- NEW: pair-lookahead waste — penalize residuals that neither the item
    // nor the next item can fully consume, scaled by how "unreachable" the
    // leftover is for typical small items
    if !is_new_bin && post_residual > 0 {
        let unreachable = post_residual as f64
            - if next_item_size > 0 { next_item_size.min(post_residual) } else { 0 } as f64;
        if unreachable > 0.0 && unreachable < 45.0 {
            score += unreachable * 0.22 * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
