        if fitting_bins_count > 0 {
            if post_residual as f64 <= cap * 0.15 {
                score += 55.0;
            }
            if post_residual <= 6 {
                score += 76.0;
            } else if post_residual <= 12 {
                score += 29.0;
            }
        }
        let item_ratio = item_size as f64 / cap;
        if fitting_bins_count > 0 && item_ratio > 0.6 {
            score -= 23.0 * (item_ratio - 0.6) * 10.0;
        }
        if open_bins_count > 3 {
            let roomy = (mean_residual / cap).min(1.0);
            score += 21.0 * roomy * (0.6 + 0.4 * progress);
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 29.0;
        }
        // Penalize fresh bin when open bins are nearly full anyway
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 32.0 * (1.0 - progress);
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
        if usable_ratio < 0.1 {
            score -= 12.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 14.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 5.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.55;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 56.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.05 * (0.5 + 0.5 * progress);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 11.5 * (1.0 - progress);
    }

    // --- Mid-range residual sink: match post-residual to common small items ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction squeeze ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (mod 10 buckets) ----
    let class = (post_residual % 10) as f64;
    // Residuals that are "harmonically useful" (multiples of 5/10) are less dead.
    let harmonic_bonus = match post_residual % 10 {
        0 => 8.0,          // perfectly divisible residual: very reusable
        5 => 4.0,          // half-class: still quite reusable
        1 | 9 => -2.0,     // nearly a multiple of 10: mildly dead
        2 | 8 => -4.0,
        3 | 7 => -6.0,
        _ => -8.0,         // 4|6: most awkward residuals
    };
    score -= harmonic_bonus * (post_residual as f64 / bin_capacity as f64);

    // ---- Integer-division threshold: how many small items (<=10) still fit ----
    let slots = post_residual / 10;
    score -= 2.0 * slots as f64;

    // ---- Lookahead coupling: does next_item_size fit into post_residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills the leftover space.
            let exact = if next_item_size == post_residual { 12.0 } else { 6.0 };
            score -= exact;
            // Harmonic match: next item's class aligns with post residual class
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 3.0;
            }
        } else {
            // Next item cannot use the leftover: leftover is likely dead weight.
            score += (post_residual as f64) * 0.15;
            // Extra penalty if leftover falls in an awkward harmonic class.
            if class >= 1.0 && class <= 4.0 || class >= 6.0 && class <= 9.0 {
                score += 4.0;
            }
        }
    }

    // ---- Last-chance bin: strongly prefer using the only fitting bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus a per-open-bin pressure so we
        // only open when existing bins would waste a lot of space.
        score = (bin_capacity as f64) * 0.55 + 3.0 * (open_bins_count as f64).sqrt();
        // If the best existing fit would leave a bad harmonic class, opening
        // a fresh bin becomes more attractive.
        if class >= 1.0 && class <= 4.0 {
            score -= 6.0;
        }
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 5.0;
        }
    }

    // ---- Waste-avoidance: near-perfect fits are gold ----
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // ---- Mild tie-break toward tighter (already partially filled) bins ----
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // ---- Mean residual coupling: penalize bins far below mean residual ----
    // (bins with unusually small residual are precious; keep them for small items)
    if (bin_residual as f64) < mean_residual - 10.0 && item_size > 40 {
        score += 5.0;
    }

    score
}

