            let item_f = item_size as f64;
            if agg_open_room > item_f * 2.0 {
                score += ((agg_open_room / item_f) - 2.0).min(6.0) * 9.0;
            }
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
        if usable_ratio < 0.1 {
            score -= 13.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 15.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 6.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.6;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 58.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.1 * (0.5 + 0.5 * progress);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- Mid-range residual sink ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // NEW: two-item lookahead chain — reward bins where post_residual matches
    // next item exactly AND the resulting residual is divisible by 25 (common
    // small-item multiples), reinforcing exact-fill chains.
    if !is_new_bin && next_item_size > 0 && next_item_size == post_residual {
        let chain_left = post_residual; // after next item it becomes 0; check divisibility of next
        let _ = chain_left;
        if next_item_size % 25 == 0 || next_item_size % 10 == 0 {
            score -= 18.0;
        }
    }

    // NEW: dead-space guard — if no open bin can absorb the next item, mildly
    // prefer bins whose post_residual stays large enough to hold it later,
    // avoiding stranding big residuals that nothing fits.
    if !is_new_bin && next_item_size > post_residual && post_residual > 25 {
        score += (post_residual - 25) as f64 * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (dead space = 0)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: a leftover gap that cannot hold the
    // lookahead item is likely unusable dead space -> penalize heavily.
    if post_residual > 0 && next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Very small slivers (< ~10% of capacity) are almost always dead space.
    if post_residual > 0 && post_residual * 10 < bin_capacity {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Reward tight fits proportionally to item size (large item into
    // nearly-exact residual is valuable).
    if bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 20.0 * tightness * (item_size as f64 / bin_capacity as f64);
        score -= 5.0; // mild baseline preference for existing bins
    }

    // New-bin candidate: base opening cost plus open_bins_count pressure
    // (many open bins -> spreading residual is fine, but a fresh bin still
    // must beat genuinely bad fits in existing bins).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.4 * open_bins_count as f64
            - 0.05 * mean_residual;
    }

    // Late in the stream, closing out bins cleanly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Sharpened tight-fit tiers ---
    if post_residual == 0 {
        score -= 1150.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 18 {
        score -= 30.0;
    } else if post_residual <= 30 {
        score -= (30 - post_residual) as f64 * 5.5;
    } else if post_residual > 45 {
        let dead = ((post_residual as f64 - 45.0) / 55.0).min(1.0);
        let dead_fits_next = next_item_size > 0 && next_item_size <= post_residual;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += dead * (42.0 + 62.0 * progress) * if dead_fits_next { 0.7 } else { 1.0 }
            * (0.75 + 0.5 * scarcity);
    }

    // --- Lookahead chain fill ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 650.0;
            if next_item_size as f64 > cap / 3.0 {
                score -= 45.0 * (1.0 - progress);
            }
        } else if next_item_size <= post_residual {
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 0.9;
            if two_step_waste <= 8 {
                score -= 85.0;
            }
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 52.0 * (1.0 - progress);
            } else if after_next <= 12 {
                score -= 17.0;
            }
            // NEW: three-step lookahead — if the item after next could also fit the
            // remaining space, this bin is a strong chain target.
            let after2 = after_next as i64 - next_item_size as i64;
            if after_next > 0 && after2 >= 0 && (after_next as u32) >= next_item_size {
                score -= 9.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let fill_ratio = (cap - post_residual as f64) / cap;
            score += 20.0 + gap * 0.55 - 48.0 * fill_ratio;
            if post_residual < 40 && next_item_size > 40 {
                score += (40 - post_residual) as f64 * 1.6;
            }
            score += gap * 0.35 * (1.0 - progress);
        }
    }

    // --- Mean-residual pull, stronger late ---
    let mean_dev = post_residual as f64 - mean_residual;
    score += mean_dev * (0.22 + 0.55 * progress);

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && !is_new_bin && bin_residual >= item_size {
        score -= 360.0;
    }

    // --- General tightness ---
    score -= (bin_capacity - bin_residual) as f64 * 0.25;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 21.0 * tightness;

    // --- Divisibility bonus ---
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 25 == 0 {
            score -= 20.0;
        } else if post_residual % 10 == 0 {
            score -= 9.0;
        }
    }

    // --- Low-utilization bins discouraged when alternatives exist ---
    let used = (bin_capacity - bin_residual) as f64;
    let util = used / cap;
    if util < 0.35 && open_bins_count > 2 && !is_new_bin {
        score += 26.0 * (0.35 - util) * (1.0 + progress);
    }

    // --- Open-bin pressure ---
    if !is_new_bin {
        score += 0.64 * open_bins_count as f64 * (1.0 - (post_residual as f64 / cap));
    }

    // --- Large items consume bins with least remaining space ---
    if !is_new_bin && item_size as f64 > cap * 0.7 {
        score -= (bin_residual - item_size) as f64 * 0.47;
    }

    // --- Near-exact fill refinement ---
    if !is_new_bin && post_residual > 0 {
        if post_residual <= 8 {
            score -= 11.0 + (8 - post_residual) as f64 * 2.5;
        } else if post_residual <= 14 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        score += 140.0 + 160.0 * progress;
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        if fitting_bins_count == 1 {
            score += 12.0;
        }
        if next_item_size > post_residual {
            score -= (next_item_size - post_residual) as f64;
        }
        score -= (open_bins_count as f64).ln().max(0.0) * 10.0;
        if progress > 0.8 {
            score += 60.0 * (progress - 0.8) * 5.0;
        }
        if next_item_size > bin_capacity / 2 {
            score -= 95.0;
        }
        if progress < 0.3 {
            score -= 42.0 * (0.3 - progress);
        }
        if next_item_size > 0 && next_item_size <= bin_residual.saturating_sub(item_size) {
            let fresh_left = bin_residual - item_size;
            if fresh_left == next_item_size {
                score -= 210.0;
            } else if next_item_size as f64 > fresh_left as f64 {
                score += (next_item_size - fresh_left) as f64 * 0.65;
            }
        }
        if open_bins_count > 4 && mean_residual > cap * 0.45 {
            score -= 16.0;
        }
        if fitting_bins_count > 0 {
            if post_residual as f64 <= cap * 0.15 {
                score += 55.0;
            }
            if post_residual <= 6 {
                score += 78.0;
            } else if post_residual <= 12 {
                score += 30.0;
            }
        }
        let item_ratio = item_size as f64 / cap;
        if fitting_bins_count > 0 && item_ratio > 0.6 {
            score -= 25.0 * (item_ratio - 0.6) * 10.0;
        }
        if open_bins_count > 3 {
            let roomy = (mean_residual / cap).min(1.0);
            score += 22.0 * roomy * (0.6 + 0.4 * progress);
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 30.0;
        }
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 34.0 * (1.0 - progress);
        }
        // NEW: refuse fresh bin when an open bin would be left with a residual the
        // next item can still consume (avoid wasting chainable space).
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_open_left = post_residual;
            if next_item_size <= best_open_left && best_open_left - next_item_size <= 10 {
                score += 90.0;
            }
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
        if usable_ratio < 0.1 {
            score -= 13.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 15.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 6.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.6;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 58.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.1 * (0.5 + 0.5 * progress);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // --- Mid-range residual sink ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // NEW: dead-space ratio refinement — penalize residuals that no remaining-typical
    // item can consume, weighted by how much stream is left (early waste is costlier).
    if !is_new_bin && post_residual > 0 {
        let unconsumable = next_item_size == 0 || next_item_size > post_residual;
        if unconsumable && post_residual as f64 > cap * 0.5 {
            score += (post_residual as f64 / cap) * 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement creates a perfect two-item chain -> strong reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves a smaller residue: mild reward,
            // scaled by how tight the eventual leftover is.
            let final_resid = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - final_resid / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space,
            // worse when the leftover is tiny (unusable).
            let r = post_residual as f64;
            if r < 10.0 {
                score += 80.0; // tiny unusable gap
            } else {
                score += 10.0 * (1.0 - r / bin_capacity as f64);
            }
        }
    }

    // Compare against mean residual of open bins: prefer bins whose residual
    // is above average (consume slack where there is plenty of it).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge relative
    // to capacity or open bins are very full on average.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 120.0 - 100.0 * fill_frac;
        // If open bins are nearly full on average, opening a new bin is fine.
        new_bin_score -= 50.0 * (mean_residual / bin_capacity as f64);
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 30.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = progress;
    let is_new_bin = bin_residual == bin_capacity;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr
        - 0.9 * t * (pr * pr) / cap
        + 0.5 * t * t * (pr * pr * pr) / (cap * cap);

    let mut score = poly;

    // Sharpened tight-fit tiers (borrowed from best heuristic, scaled down).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 4 {
        score -= 180.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 18 {
        score -= 22.0;
    } else if post_residual <= 30 {
        score -= (30 - post_residual) as f64 * 3.5;
    } else if post_residual > 45 {
        let dead = ((post_residual - 45) as f64 / 55.0).min(1.0);
        let dead_fits_next = next_item_size > 0 && next_item_size <= post_residual;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += dead * (30.0 + 45.0 * t) * if dead_fits_next { 0.7 } else { 1.0 }
            * (0.75 + 0.5 * scarcity);
    }

    // Lookahead chain fill (two-step waste reasoning).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 480.0;
            if nxt > cap / 3.0 {
                score -= 30.0 * (1.0 - t);
            }
        } else if next_item_size <= post_residual {
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 0.9;
            if two_step_waste <= 8 {
                score -= 60.0;
            }
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 38.0 * (1.0 - t);
            } else if after_next <= 12 {
                score -= 12.0;
            }
        } else {
            let gap = nxt - pr;
            score += 15.0 + gap * 0.45;
            if post_residual < 40 && next_item_size > 40 {
                score += (40 - post_residual) as f64 * 1.1;
            }
            score += gap * 0.3 * (1.0 - t);
        }
    } else {
        // Last item: any residual is pure waste; strongly favor tightest fit.
        score += 3.0 * pr;
    }

    // Mean-residual pull, stronger late.
    let mean_dev = pr - mean_residual;
    score += mean_dev * (0.2 + 0.5 * t);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 250.0 + 60.0 * t;
    }

    // General tightness terms.
    score -= (bin_capacity - bin_residual) as f64 * 0.2;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Large items consume bins with least remaining space.
    if !is_new_bin && item_size as f64 > cap * 0.7 {
        score -= (bin_residual - item_size) as f64 * 0.4;
    }

    // Open-bin pressure: discourage spreading across many bins.
    if !is_new_bin {
        score += 0.5 * open_bins_count as f64 * (1.0 - pr / cap);
    }

    // Low-utilization bins discouraged when alternatives exist.
    if !is_new_bin {
        let used = (bin_capacity - bin_residual) as f64;
        let util = used / cap;
        if util < 0.35 && open_bins_count > 2 {
            score += 20.0 * (0.35 - util) * (1.0 + t);
        }
    }

    // New-bin candidate handling: penalize mildly but yield under pressure.
    if is_new_bin {
        let fragmentation = (mean_residual / cap).max(0.0);
        let pressure = if open_bins_count > 0 { 1.0 / open_bins_count as f64 } else { 1.0 };
        score += 110.0 + 130.0 * t
            - 90.0 * fragmentation * fragmentation
            - 60.0 * pressure * t;

        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if fitting_bins_count == 1 {
            score += 10.0;
        }
        // Fresh bin lookahead: reward if it can chain the next item exactly.
        if next_item_size > 0 && next_item_size <= bin_residual.saturating_sub(item_size) {
            let fresh_left = bin_residual - item_size;
            if fresh_left == next_item_size {
                score -= 150.0;
            } else if next_item_size as f64 > fresh_left as f64 {
                score += (next_item_size - fresh_left) as f64 * 0.55;
            }
        }
        if next_item_size > bin_capacity / 2 {
            score -= 70.0;
        }
        if open_bins_count > 4 && mean_residual > cap * 0.45 {
            score -= 14.0;
        }
        // Penalize fresh bin when an open bin would end nearly empty anyway.
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 30.0 * (1.0 - t);
        }
        if fitting_bins_count > 0 {
            if pr <= cap * 0.15 {
                score += 40.0;
            }
            if post_residual <= 6 {
                score += 55.0;
            } else if post_residual <= 12 {
                score += 22.0;
            }
        }
        let item_ratio = item_size as f64 / cap;
        if fitting_bins_count > 0 && item_ratio > 0.6 {
            score -= 18.0 * (item_ratio - 0.6) * 10.0;
        }
    }

    // Fragmentation-aware tiebreak for open bins.
    if !is_new_bin && post_residual > 0 {
        let usable_ratio = pr / cap;
        if usable_ratio < 0.1 {
            score -= 10.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 5.0;
        }
    }

    // Prefer tightest when many bins fit.
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.3;
    }

    // Dead-space ratio penalty scaled by remaining stream, with lookahead relief.
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > pr {
            score += dead_ratio * 45.0 * (0.5 + 0.5 * t);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.0 * (0.5 + 0.5 * t);
            }
        }
    }

    // Reward using bins whose residual is awkwardly small for typical items.
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 10.0 * (1.0 - t);
    }

    // Mid-range residual sink: prefer bins whose post-residual matches small items.
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // Late-stream compaction — squeeze harder as stream ends.
    if !is_new_bin && t > 0.85 && post_residual > 0 {
        score += (pr / cap) * 12.0 * (t - 0.85) * 6.0;
    }

    score
}

