        }
    }

    // --- MUTATION: residual-parity match with next item (divisibility harmony) ---
    if !is_new_bin && next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
        score -= 14.0;
    }

