    // closest to the mean residual (keeps residual distribution compact) ---
    if fitting_bins_count > 3 && !is_new_bin {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.35;
    }

    // --- MUTATION: squeeze large items into nearly-full bins late ---
    if !is_new_bin && progress > 0.7 && bin_residual < bin_capacity / 4 && bin_residual >= item_size {
        score -= 30.0 * (progress - 0.7) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 partition dead space
    // into "harmonically useful" classes (e.g. 50, 25, 20 are reusable by
    // common item sizes) vs. awkward ones.
    let pr = post_residual;
    let class = pr % 10;

    // Reward post_residuals that are multiples of common sizes (10,20,25,50)
    if pr > 0 && (pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0) {
        score -= 6.0;
    }
    // Penalize awkward residues (1..9 dead space)
    if class > 0 && class < 5 {
        score += 2.0 + class as f64;
    } else if class >= 5 {
        score += 1.0;
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item fits the post residual comfortably, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post residual becomes dead space for the next item
        score += 5.0;
    }

    // Integer-division threshold: post_residual <= 10 is essentially dead
    if pr <= 10 && pr > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // or the fit here would leave large unusable residue.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64 * mean_residual) < (open_bins_count.max(1) as f64 * 15.0);
        let penalty = if crowded { 0.0 } else { 18.0 };
        score += 10.0 + penalty - 6.0 * progress;
    }

    // Prefer tighter bins generally (best-fit flavor scaled by harmonics)
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Mean-residual coupling: if this bin is far below mean residual,
    // it's already tight; reward using it.
    if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 3.0;
    }

    score
}

