                score += 70.0;
            } else if post_residual <= 12 {
                score += 27.0;
            }
        }
        let item_ratio = item_size as f64 / cap;
        if fitting_bins_count > 0 && item_ratio > 0.6 {
            score -= 22.0 * (item_ratio - 0.6) * 10.0;
        }
        if open_bins_count > 3 {
            let roomy = (mean_residual / cap).min(1.0);
            score += 20.0 * roomy * (0.6 + 0.4 * t);
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 27.0;
        }
        if fitting_bins_count > 0 && mean_residual < cap * 0.12 {
            score += 30.0 * (1.0 - t);
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = pr / cap;
        if usable_ratio < 0.1 {
            score -= 12.0 * (0.1 - usable_ratio) * 100.0;
        }
        if post_residual > 90 && post_residual < bin_capacity {
            score += 14.0;
        }
        if post_residual >= 20 && post_residual <= 60 {
            score -= 5.0;
        }
    }

    // --- Prefer tightest when many bins fit ---
    if fitting_bins_count > 2 && !is_new_bin {
        score += fitting_bins_count as f64 * 1.5;
    }

    // --- Dead-space ratio penalty scaled by remaining stream ---
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (pr - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > pr {
            score += dead_ratio * 52.0 * (0.5 + 0.5 * t);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.0 * (0.5 + 0.5 * t);
            }
        }
    }

    // --- Reward using bins whose residual is awkwardly small for typical items ---
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 11.0 * (1.0 - t);
    }

    // --- Mid-range residual sink: match common small item sizes ---
    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction — squeeze harder as stream ends ---
    if !is_new_bin && t > 0.85 && post_residual > 0 {
        score += (pr / cap) * 13.0 * (t - 0.85) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Residuals below the minimum item size (1..100 domain -> threshold ~20) are wasted.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0; // unusable sliver penalty
    }

    // Non-linear reward for tight fits (post_residual near zero but usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 15.0;

    // Penalize bins whose residual is barely above the item (awkward fit).
    let slack = (bin_residual - item_size) as f64;
    if slack > 0.0 && slack < 10.0 {
        score += (10.0 - slack) * 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: more open bins -> favor filling existing ones over new bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap that next item cannot use: mild penalty
        score += 3.0;
    }

    // Mean residual coupling: when open bins are generally full, prefer new bin less.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // New-bin candidate baseline: make empty bin moderately attractive only when
    // existing bins would create dead space (handled above); otherwise keep it costly.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
