    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when post_residual matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Perfect chain: next item fills bin to near zero.
            let chain_gap = post_residual as f64 - next;
            score -= 35.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
