            score += 12.0 * (next / bin_capacity as f64);
        }
    } else {
        // Last item: any placement is fine, slightly prefer exact fill.
        score -= 5.0;
    }

    // Coupling with mean residual: bins below mean residual are already tight;
    // using them aggressively is good, but avoid leaving tiny scraps.
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= 6.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mr) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin is acceptable early or when nothing fits well elsewhere.
        if fitting_bins_count > 0 {
            let best_possible = if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 { 0.0 } else { 15.0 };
            score += 18.0 + best_possible + 10.0 * (1.0 - progress);
        } else {
            // No open bin fits: opening new bin is required; neutral score.
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

