    // Dead-space ratio penalty scaled by remaining stream
    if !is_new_bin && post_residual > 30 {
        let dead_ratio = (post_residual as f64 - 30.0) / cap;
        if next_item_size == 0 || next_item_size as f64 > post_residual as f64 {
            score += dead_ratio * 52.0 * (0.5 + 0.5 * progress);
        } else {
            let leftover = post_residual - next_item_size;
            if leftover > 20 {
                score += (leftover - 20) as f64 * 1.0 * (0.5 + 0.5 * progress);
            }
        }
    }

    // Reward using bins whose residual is awkwardly small for typical items
    if !is_new_bin && post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 + 8.0 * (6 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space that nothing typical could use: residual too small
    // relative to the smallest plausible item (interface floor = 1, but
    // statistically small residuals are still waste).
    let dead_threshold = 3.0;
    if (post_residual as f64) > dead_threshold {
        // Waste grows super-linearly for large leftovers on mostly-empty bins.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.35 && post_residual > 40 {
            score += 0.15 * (post_residual as f64 - 40.0);
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly
    // favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 5 {
                score -= 40.0 - 5.0 * chain_waste as f64;
            }
        } else {
            // Next item won't fit here after placement: mild penalty, this bin
            // becomes "closed" for the lookahead horizon.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // when the fit here would leave a large awkward residual, or when many
    // bins are open and mean residual is low (fragmentation regime).
    if bin_residual == bin_capacity {
        // Baseline neutral-ish score: penalize opening bins early in stream,
        // reward when fragmentation is high.
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * progress;
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 20.0; // fragmentation: fresh bin better than squeezing
        }
        if item_size >= 60 {
            score -= 10.0; // big items like fresh bins
        }
    }

    // Prefer tighter bins generally: tighter fit => smaller residual gap to mean.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Time horizon: late in the stream, close bins out aggressively — favor
    // bins that will be nearly full (avoid leaving many half-empty bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.85 {
        score += 0.3 * post_residual as f64 * progress;
    }

    // Small global coupling: with many open bins, slightly prefer bins below
    // mean residual (balance load and keep large residuals available).
    if open_bins_count > 3 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
