    if !is_new_bin && post_residual >= 5 && post_residual <= 15 && next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // --- Late-stream compaction — squeeze harder as stream ends ---
    if !is_new_bin && progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 14.0 * (progress - 0.85) * 6.0;
    }

    // --- NEW: two-step exact-fill chase — reward bins whose residual equals the
    // sum of the next item and a plausible small follow-up (5..=20) ---
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if (5..=20).contains(&after) {
            score -= 10.0 + (20 - after) as f64 * 0.8 * (1.0 - progress);
