    }

    // --- NEW: residual-vs-mean coupling — bins that end closer to the fleet mean
    // keep the residual distribution compact, easing future fits ---
    if !is_new_bin && post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev < 8.0 {
            score -= 4.0 * (8.0 - dev) * (0.4 + 0.6 * progress);
        }
    }

    score
}

