        // item cannot use anyway — those leftovers are equally dead.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_alt = if next_item_size <= post_residual { post_residual - next_item_size } else { post_residual };
            if best_alt >= next_item_size {
                score += 20.0;
            }
        }
    }

    // --- Fragmentation-aware tiebreak ---
    if post_residual > 0 && !is_new_bin {
        let usable_ratio = post_residual as f64 / cap;
